/**
 * View 侧（Electron Main / 调试 CLI / 测试）共用的协议客户端：
 * 在 JsonlChannel 之上做 requestId 配对、超时、反向请求回包与事件分发。
 * 不关心进程如何拉起——由调用方传入子进程的 stdout/stdin。
 */
import type { Readable, Writable } from 'node:stream';

import {
  RuntimeRpcError,
  errorCodeOf,
  makeError,
  type Envelope,
  type JsonRpcError,
  type LogEnvelope,
  type PhaseEnvelope,
  type ExitEnvelope,
  type NotificationEnvelope,
  type ServerRequestEnvelope,
} from '../index';
import { JsonlChannel, createIdGenerator } from './channel';

/** 通道断开时 pending 请求统一以此码 reject，UI 才能区分“进程没了”与业务失败 */
function channelClosedError(reason: string, cause?: Error): RuntimeRpcError {
  return new RuntimeRpcError(
    makeError('CODEX_NOT_RUNNING', cause ? `${reason}: ${cause.message}` : reason),
  );
}

export interface RpcClientOptions {
  input: Readable;
  output: Writable;
  /** 默认请求超时，毫秒；0 = 不超时 */
  defaultTimeoutMs?: number;
  onDecodeError?: (message: string) => void;
  /** 写入子进程 stdin 失败（EPIPE 等）；通道随即关闭并 reject 所有 pending */
  onWriteError?: (error: Error) => void;
}

export interface RequestOptions {
  timeoutMs?: number;
  /** Keep tracking a timed-out wire request until its response or connection close. */
  onTimeout?: () => void;
  onSettled?: () => void;
}

export class RpcRequestTimeoutError extends Error {}

type Listener<T> = (payload: T) => void;

export class RuntimeRpcClient {
  readonly channel: JsonlChannel;
  private readonly nextId = createIdGenerator('req');
  private readonly pending = new Map<
    string,
    { resolve(value: unknown): void; reject(error: Error): void; timer?: ReturnType<typeof setTimeout>; method: string; settled?: () => void; unknown?: () => void; trackingId?: string }
  >();
  private readonly earlySettlements = new Set<string>();
  private readonly notificationListeners = new Set<Listener<NotificationEnvelope>>();
  private readonly serverRequestListeners = new Set<Listener<ServerRequestEnvelope>>();
  private readonly phaseListeners = new Set<Listener<PhaseEnvelope>>();
  private readonly logListeners = new Set<Listener<LogEnvelope>>();
  private readonly exitListeners = new Set<Listener<ExitEnvelope>>();
  private readonly closeListeners = new Set<() => void>();
  private readonly defaultTimeoutMs: number;

  constructor(options: RpcClientOptions) {
    this.defaultTimeoutMs = options.defaultTimeoutMs ?? 30_000;
    this.channel = new JsonlChannel({
      input: options.input,
      output: options.output,
      onDecodeError: (result) => {
        options.onDecodeError?.(`${result.error}: ${result.raw}`);
        if (result.error === 'line-too-large') {
          this.rejectAll(new RuntimeRpcError(makeError('HISTORY_TOO_LARGE', 'A protocol message exceeds the desktop transport limit')));
        }
      },
      onInvalidEnvelope: (_value, error) => options.onDecodeError?.(`invalid envelope: ${error}`),
      onWriteError: (error) => options.onWriteError?.(error),
    });
    this.channel.onMessage((envelope) => this.handle(envelope));
    this.channel.onClose((error) => {
      this.rejectAll(channelClosedError('runtime channel closed', error));
      for (const listener of this.closeListeners) listener();
    });
  }

  request<T = unknown>(method: string, params?: unknown, options: RequestOptions = {}): Promise<T> {
    const requestId = this.nextId();
    const timeoutMs = options.timeoutMs ?? this.defaultTimeoutMs;
    return new Promise<T>((resolve, reject) => {
      const entry = {
        method,
        resolve: resolve as (value: unknown) => void,
        reject,
        timer: undefined as ReturnType<typeof setTimeout> | undefined,
        settled: options.onSettled,
        unknown: options.onTimeout,
        trackingId: undefined as string | undefined,
      };
      if (timeoutMs > 0) {
        entry.timer = setTimeout(() => {
          if (!options.onSettled) this.pending.delete(requestId);
          options.onTimeout?.();
          reject(new RpcRequestTimeoutError(`${method} timed out after ${timeoutMs} ms`));
        }, timeoutMs);
      }
      this.pending.set(requestId, entry);
      const sent = this.channel.send({ type: 'request', requestId, method, params });
      if (!sent && this.pending.delete(requestId)) {
        if (entry.timer) clearTimeout(entry.timer);
        entry.settled?.();
        reject(channelClosedError(`${method} could not be sent; the runtime channel is closed`));
      }
    });
  }

  /** 回复 Runtime 发来的 serverRequest */
  respond(requestId: string, result: unknown): boolean {
    return this.channel.send({ type: 'serverResponse', requestId, result });
  }

  respondError(requestId: string, error: JsonRpcError): boolean {
    return this.channel.send({ type: 'serverResponse', requestId, error });
  }

  onNotification(listener: Listener<NotificationEnvelope>) {
    this.notificationListeners.add(listener);
    return () => this.notificationListeners.delete(listener);
  }
  onServerRequest(listener: Listener<ServerRequestEnvelope>) {
    this.serverRequestListeners.add(listener);
    return () => this.serverRequestListeners.delete(listener);
  }
  onPhase(listener: Listener<PhaseEnvelope>) {
    this.phaseListeners.add(listener);
    return () => this.phaseListeners.delete(listener);
  }
  onLog(listener: Listener<LogEnvelope>) {
    this.logListeners.add(listener);
    return () => this.logListeners.delete(listener);
  }
  onExit(listener: Listener<ExitEnvelope>) {
    this.exitListeners.add(listener);
    return () => this.exitListeners.delete(listener);
  }
  onClose(listener: () => void) {
    this.closeListeners.add(listener);
    return () => this.closeListeners.delete(listener);
  }

  /** 等待某个通知出现（测试 / CLI 用） */
  waitForNotification(
    predicate: (notification: NotificationEnvelope) => boolean,
    timeoutMs = 10_000,
  ): Promise<NotificationEnvelope> {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        off();
        reject(new Error('Timed out while waiting for a notification'));
      }, timeoutMs);
      const off = this.onNotification((notification) => {
        if (!predicate(notification)) return;
        clearTimeout(timer);
        off();
        resolve(notification);
      });
    });
  }

  close() {
    this.rejectAll(channelClosedError('runtime client closed'));
    this.channel.close();
  }

  get pendingCount() {
    return this.pending.size;
  }

  private handle(envelope: Envelope) {
    switch (envelope.type) {
      case 'response': {
        const entry = this.pending.get(envelope.requestId);
        if (!entry) return;
        if (entry.timer) clearTimeout(entry.timer);
        const data = envelope.error?.data as { trackingId?: unknown } | undefined;
        if (entry.settled && errorCodeOf(envelope.error) === 'RESULT_UNKNOWN'
          && typeof data?.trackingId === 'string' && data.trackingId.length <= 128) {
          entry.trackingId = data.trackingId;
          entry.unknown?.();
          entry.reject(new RuntimeRpcError(envelope.error!));
          if (this.earlySettlements.delete(entry.trackingId)) {
            this.pending.delete(envelope.requestId); entry.settled();
          }
          return;
        }
        this.pending.delete(envelope.requestId);
        if (envelope.error) entry.reject(new RuntimeRpcError(envelope.error));
        else entry.resolve(envelope.result);
        entry.settled?.();
        return;
      }
      case 'notification':
        if (envelope.method === 'runtime/requestSettled') {
          const trackingId = (envelope.params as { trackingId?: unknown } | undefined)?.trackingId;
          if (typeof trackingId === 'string' && trackingId.length <= 128) {
            const match = [...this.pending].find(([, entry]) => entry.trackingId === trackingId);
            if (match) { this.pending.delete(match[0]); match[1].settled?.(); }
            else {
              this.earlySettlements.add(trackingId);
              if (this.earlySettlements.size > 1024) this.earlySettlements.delete(this.earlySettlements.values().next().value!);
            }
          }
        }
        for (const listener of this.notificationListeners) listener(envelope);
        return;
      case 'serverRequest':
        for (const listener of this.serverRequestListeners) listener(envelope);
        return;
      case 'phase':
        for (const listener of this.phaseListeners) listener(envelope);
        return;
      case 'log':
        for (const listener of this.logListeners) listener(envelope);
        return;
      case 'exit':
        for (const listener of this.exitListeners) listener(envelope);
        return;
      default:
        // request / serverResponse 是 View → Runtime 方向，客户端不处理
        return;
    }
  }

  rejectPending(error: Error) {
    this.rejectAll(error);
  }

  private rejectAll(error: Error) {
    this.earlySettlements.clear();
    const entries = [...this.pending.values()];
    this.pending.clear();
    for (const entry of entries) {
      if (entry.timer) clearTimeout(entry.timer);
      entry.reject(error);
      entry.settled?.();
    }
  }
}
